 if(a==='wdhome'){wdStop();v.s='path';v.subj='write';return true}
 var S=v.wd;if(!S||v.s!=='wd'||S.ownerId!==db.active)return false;
 var d=wdDoc(S.id),p=wdP();if(!d)return false;
