 h+='<rect x="196" y="92" width="80" height="30" rx="6" fill="#0E7C86"/><rect x="202" y="97" width="44" height="14" rx="2" fill="#1d3b2a"/><text x="224" y="108" text-anchor="middle" font-size="9" font-family="monospace" fill="#7CFFB2">ABC</text><circle cx="258" cy="104" r="5" fill="#ffd43b"/><circle cx="270" cy="104" r="3" fill="#f08c00"/>';
 return '<svg viewBox="0 0 320 180" aria-hidden="true" class="work-art">'+h+'</svg>';
